{"mode":"feedback","data":{"case_id":"G01","source_case_id":"Q05","template_id":"python-learning-csv","template_version":"1.0","task":"输入语法良好的CSV字符串；必需列record_id、duration_minutes，额外已命名列忽略。record_id须int可解析且>0；分钟空白为未知，非空须int可解析且0至1440。每行独立，不要求跨行去重，空白物理行由csv忽略。缺表头抛ValueError；非法行计invalid_count。已知0与未知分开。返回五个计数字段。函数不读写文件、不联网、不执行任意代码。平台仅静态评审，不运行学生代码。","criterion_ids":["C01"],"criterion":{"criterion_id":"C01","name":"表头约束","issue_types":["missing_header_validation"]},"reference":{"reference_label":"needs_changes","reference_criteria":{"C01":"fail","C02":"pass","C03":"pass","C04":"pass","C05":"pass","C06":"pass"},"reference_issues":[{"criterion_id":"C01","issue_type":"missing_header_validation","reference_reason":"缺少必需列时应抛ValueError，不返回空字典"}],"reference_action":"缺少必需列时应抛ValueError，不返回空字典"},"student_code":"import csv
import io

def summarize_records(csv_text: str) -> dict:
    reader = csv.DictReader(io.StringIO(csv_text))
    required = {"record_id", "duration_minutes"}
    if reader.fieldnames is None or not required.issubset(reader.fieldnames):
        return {}
    out = {"record_count": 0, "known_duration_count": 0, "known_minutes": 0,
           "missing_duration_count": 0, "invalid_count": 0}
    for row in reader:
        try:
            if None in row:
                raise ValueError("extra unheaded field")
            rid = int(row["record_id"].strip())
            raw = row["duration_minutes"].strip()
            duration = None if raw == "" else int(raw)
            if rid <= 0 or (duration is not None and not 0 <= duration <= 1440):
                raise ValueError("out of range")
        except (ValueError, TypeError, AttributeError):
            out["invalid_count"] += 1
            continue
        out["record_count"] += 1
        if duration is None:
            out["missing_duration_count"] += 1
        else:
            out["known_duration_count"] += 1
            out["known_minutes"] += duration
    return out
